const ACTIVE_ALERT_STATES = new Set([
  "pending",
  "sending",
  "retryable_failure"
]);
const MAXIMUM_MANUAL_ACTION_FINGERPRINTS = 100;
const MINUTE_MS = 60 * 1000;

function timestamp(value) {
  const parsed = Date.parse(String(value || ""));
  return Number.isFinite(parsed) ? parsed : undefined;
}

function ageMinutes(nowMs, dueMs) {
  if (!Number.isFinite(dueMs)) return null;
  return Math.round(Math.max(0, nowMs - dueMs) / MINUTE_MS * 1000) / 1000;
}

function oldestAge(nowMs, timestamps) {
  if (timestamps.length === 0) return null;
  return ageMinutes(nowMs, Math.min(...timestamps));
}

function recordLocator(record) {
  const rowNumber = String(record?.row_number ?? "").trim();
  if (rowNumber) return `row:${rowNumber}`;
  return `id:${String(record?.canonical_job_id || "").trim()}`;
}

function summarizeWorkBacklog(
  activeRows,
  schema,
  now,
  processingLeaseMs
) {
  const nowMs = Date.parse(now);
  const rawByLocator = new Map(
    activeRows.map((raw) => {
      const normalized = normalizeLegacyRecord(raw, schema, now);
      return [recordLocator(normalized), raw];
    })
  );
  const candidates = selectWorkCandidates(activeRows, schema, {
    now,
    maxItems: Math.max(1, activeRows.length),
    leaseMs: processingLeaseMs.generation
  });
  const stageSummary = (stage) => {
    const stageCandidates = candidates.filter(
      (record) => record.work_stage === stage
    );
    const dueTimestamps = stageCandidates
      .map((record) =>
        workCandidateDueAt(
          record,
          stage,
          processingLeaseMs[stage],
          rawByLocator.get(recordLocator(record))
        )
      )
      .filter((value) => Number.isFinite(value) && value <= nowMs);
    return {
      count: stageCandidates.length,
      oldest_minutes: oldestAge(nowMs, dueTimestamps),
      age_unobservable_count:
        stageCandidates.length - dueTimestamps.length
    };
  };
  const generation = stageSummary("generation");
  const evaluation = stageSummary("evaluation");
  return {
    due_generation_count: generation.count,
    oldest_due_generation_minutes: generation.oldest_minutes,
    generation_age_unobservable_count:
      generation.age_unobservable_count,
    due_evaluation_count: evaluation.count,
    oldest_due_evaluation_minutes: evaluation.oldest_minutes,
    evaluation_age_unobservable_count:
      evaluation.age_unobservable_count
  };
}

function alertOrigin(record) {
  return (
    timestamp(record.generated_at) ??
    timestamp(record.alert_last_attempt_at) ??
    timestamp(record.alert_next_retry_at) ??
    timestamp(record.updated_at) ??
    timestamp(record.created_at)
  );
}

function summarizeAlertBacklog(records, nowMs) {
  const pending = records.filter((record) =>
    ACTIVE_ALERT_STATES.has(String(record.alert_status || "").trim())
  );
  const origins = pending
    .map((record) => alertOrigin(record))
    .filter((value) => Number.isFinite(value) && value <= nowMs);
  return {
    pending_alert_count: pending.length,
    oldest_pending_alert_minutes: oldestAge(nowMs, origins),
    pending_alert_age_unobservable_count:
      pending.length - origins.length
  };
}

function fingerprint(value) {
  let hash = 0xcbf29ce484222325n;
  for (const character of String(value)) {
    hash ^= BigInt(character.codePointAt(0));
    hash = BigInt.asUintN(64, hash * 0x100000001b3n);
  }
  return hash.toString(16).padStart(16, "0");
}

function sourceActionEntries(records, location) {
  return records.flatMap((record) => {
    const action = String(record.manual_action || "").trim();
    if (!action) return [];
    return [
      [
        location,
        record.canonical_job_id || record.row_number || "",
        stateGuard(record),
        action
      ].join("\u001f")
    ];
  });
}

function projectionActionEntries(rows, location) {
  return rows.flatMap((row) => {
    const action = String(row?.Action || "").trim();
    if (!action) return [];
    return [
      [
        location,
        row.canonical_job_id || row.row_number || "",
        row.source_state_guard || "",
        action
      ].join("\u001f")
    ];
  });
}

function summarizeManualActions({
  activeRecords,
  archiveRecords,
  queueRows,
  appliedJobsRows
}) {
  const entries = [
    ...sourceActionEntries(activeRecords, "active"),
    ...sourceActionEntries(archiveRecords, "archive"),
    ...projectionActionEntries(queueRows, "review_queue"),
    ...projectionActionEntries(appliedJobsRows, "applied_jobs")
  ];
  const allFingerprints = [...new Set(entries.map(fingerprint))].sort();
  const fingerprints = allFingerprints.slice(
    0,
    MAXIMUM_MANUAL_ACTION_FINGERPRINTS
  );
  return {
    manual_action_count: entries.length,
    manual_action_fingerprints: fingerprints,
    manual_action_fingerprints_truncated:
      Math.max(0, allFingerprints.length - fingerprints.length)
  };
}

function summarizeActiveClaims(records, nowMs, processingLeaseMs) {
  let pastLeaseCount = 0;
  let invalidCount = 0;
  const expiredAt = [];
  for (const record of records) {
    const stage = String(record.processing_stage || "").trim();
    const token = String(record.processing_token || "").trim();
    const startedAtText = String(record.processing_started_at || "").trim();
    if (!stage && !token && !startedAtText) continue;
    const leaseMs = Number(processingLeaseMs?.[stage]);
    const startedAt = timestamp(startedAtText);
    if (
      !stage ||
      !token ||
      !startedAtText ||
      !Number.isFinite(leaseMs) ||
      leaseMs < 1 ||
      !Number.isFinite(startedAt) ||
      startedAt > nowMs
    ) {
      invalidCount += 1;
      pastLeaseCount += 1;
      continue;
    }
    const expiresAt = startedAt + leaseMs;
    if (expiresAt <= nowMs) {
      pastLeaseCount += 1;
      expiredAt.push(expiresAt);
    }
  }
  return {
    active_claim_past_lease_count: pastLeaseCount,
    invalid_active_claim_marker_count: invalidCount,
    oldest_active_claim_past_lease_minutes: oldestAge(nowMs, expiredAt)
  };
}

function summarizeOperationalBacklog(
  {
    activeRows = [],
    archiveRows = [],
    queueRows = [],
    appliedJobsRows = []
  },
  schema,
  {
    now = new Date().toISOString(),
    generationLeaseMs,
    processingLeaseMs = {}
  } = {}
) {
  const nowMs = Date.parse(now);
  if (!Number.isFinite(nowMs)) {
    throw new Error("operational backlog summary requires a valid timestamp");
  }
  if (!Number.isFinite(generationLeaseMs) || generationLeaseMs < 1) {
    throw new Error(
      "operational backlog summary requires a positive generation lease"
    );
  }
  const normalizedActive = activeRows.map((row) =>
    normalizeLegacyRecord(row, schema, now)
  );
  const normalizedArchive = archiveRows.map((row) =>
    normalizeLegacyRecord(row, schema, now)
  );
  return {
    ...summarizeWorkBacklog(
      activeRows,
      schema,
      now,
      {
        ...processingLeaseMs,
        generation: generationLeaseMs
      }
    ),
    ...summarizeAlertBacklog(normalizedActive, nowMs),
    ...summarizeManualActions({
      activeRecords: normalizedActive,
      archiveRecords: normalizedArchive,
      queueRows,
      appliedJobsRows
    }),
    ...summarizeActiveClaims(
      [...normalizedActive, ...normalizedArchive],
      nowMs,
      processingLeaseMs
    )
  };
}

function generatorResultEvent(record, stage) {
  return {
    event: "generator_result",
    timestamp: String(record?.updated_at || "").trim(),
    state_commit_pending: true,
    stage: String(stage || record?.failed_stage || "").trim(),
    status: String(record?.pipeline_status || "").trim(),
    category: String(record?.error_category || "").trim()
  };
}


const POLICY_VERSION_PATTERN = /^\d{4}-\d{2}-\d{2}\/v\d+$/;
const MODEL_ID_PATTERN = /^[a-z0-9][a-z0-9._/-]*$/i;

function validDateOnly(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value ?? "")) return false;
  const parsed = new Date(`${value}T00:00:00.000Z`);
  return (
    Number.isFinite(parsed.getTime()) &&
    parsed.toISOString().slice(0, 10) === value
  );
}

function finiteNonNegative(value) {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

function positiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

function groqModelById(policy, modelId) {
  return (policy?.models ?? []).find((model) => model.id === modelId);
}

function validateGroqProviderPolicy(
  policy,
  now = new Date().toISOString()
) {
  const errors = [];
  if (!policy || typeof policy !== "object") {
    return ["Groq provider policy must be an object"];
  }
  if (policy.schema_version !== 1) {
    errors.push("Groq provider policy schema_version must be 1");
  }
  if (!POLICY_VERSION_PATTERN.test(policy.policy_version ?? "")) {
    errors.push("Groq provider policy_version must use YYYY-MM-DD/vN");
  }
  if (policy.provider !== "groq") {
    errors.push("Groq provider policy provider must be groq");
  }
  if (!validDateOnly(policy.last_verified_on)) {
    errors.push("Groq provider last_verified_on must be a valid date");
  }
  if (!MODEL_ID_PATTERN.test(policy.selected_model ?? "")) {
    errors.push("Groq selected_model is invalid");
  }

  const generation = policy.generation ?? {};
  if (
    !finiteNonNegative(generation.temperature) ||
    generation.temperature > 1
  ) {
    errors.push("Groq generation temperature must be between 0 and 1");
  }
  for (const field of [
    "maximum_output_tokens",
    "maximum_combined_input_characters",
    "repair_reserve_characters",
    "maximum_prompt_proofs",
    "character_estimate_divisor",
    "request_interval_ms"
  ]) {
    if (!positiveInteger(generation[field])) {
      errors.push(`Groq generation ${field} must be a positive integer`);
    }
  }
  if (
    positiveInteger(generation.maximum_combined_input_characters) &&
    positiveInteger(generation.repair_reserve_characters) &&
    generation.repair_reserve_characters >=
      generation.maximum_combined_input_characters
  ) {
    errors.push("Groq repair reserve must be smaller than the input budget");
  }
  if (
    positiveInteger(generation.request_interval_ms) &&
    generation.request_interval_ms <= 60_000
  ) {
    errors.push("Groq request interval must exceed the one-minute rate window");
  }

  if (!Array.isArray(policy.models) || policy.models.length === 0) {
    errors.push("Groq models must be a non-empty array");
  }
  const modelIds = new Set();
  for (const model of policy.models ?? []) {
    if (!MODEL_ID_PATTERN.test(model?.id ?? "")) {
      errors.push("Groq policy contains an invalid model id");
      continue;
    }
    if (modelIds.has(model.id)) {
      errors.push(`Groq policy contains duplicate model id: ${model.id}`);
    }
    modelIds.add(model.id);
    if (!["production", "preview", "deprecated"].includes(model.lifecycle)) {
      errors.push(`Groq model ${model.id} has an invalid lifecycle`);
    }
    if (typeof model.artifact_approved !== "boolean") {
      errors.push(`Groq model ${model.id} must declare artifact approval`);
    }
    if (
      !["ready", "benchmark_required", "forbidden"].includes(
        model.production_activation
      )
    ) {
      errors.push(`Groq model ${model.id} has an invalid activation status`);
    }
    if (model.shutdown_on !== null && !validDateOnly(model.shutdown_on)) {
      errors.push(`Groq model ${model.id} has an invalid shutdown date`);
    }
    for (const field of [
      "context_window_tokens",
      "provider_maximum_output_tokens"
    ]) {
      if (!positiveInteger(model[field])) {
        errors.push(`Groq model ${model.id} ${field} must be positive`);
      }
    }
    for (const field of [
      "requests_per_minute",
      "requests_per_day",
      "tokens_per_minute",
      "tokens_per_day"
    ]) {
      if (!positiveInteger(model.developer_base_limits?.[field])) {
        errors.push(`Groq model ${model.id} limit ${field} must be positive`);
      }
    }
    for (const [field, value] of Object.entries(
      model.pricing_usd_per_million_tokens ?? {}
    )) {
      if (value !== null && !finiteNonNegative(value)) {
        errors.push(`Groq model ${model.id} price ${field} is invalid`);
      }
    }
    if (
      !Array.isArray(model.official_sources) ||
      model.official_sources.length === 0 ||
      model.official_sources.some(
        (source) =>
          typeof source !== "string" ||
          !source.startsWith("https://console.groq.com/docs/")
      )
    ) {
      errors.push(`Groq model ${model.id} must cite official Groq sources`);
    }
  }

  const selected = groqModelById(policy, policy.selected_model);
  if (!selected) {
    errors.push("Groq selected_model is absent from models");
  } else {
    if (selected.artifact_approved !== true) {
      errors.push("Groq selected_model is not approved for generated artifacts");
    }
    if (selected.production_activation === "forbidden") {
      errors.push("Groq selected_model is forbidden for production activation");
    }
    if (selected.lifecycle === "deprecated") {
      errors.push("Groq selected_model is deprecated");
    }
    if (
      positiveInteger(generation.maximum_output_tokens) &&
      positiveInteger(selected.provider_maximum_output_tokens) &&
      generation.maximum_output_tokens >
        selected.provider_maximum_output_tokens
    ) {
      errors.push("Groq output cap exceeds the selected provider model limit");
    }
    const nowDate = String(now).slice(0, 10);
    if (
      selected.shutdown_on &&
      validDateOnly(nowDate) &&
      nowDate >= selected.shutdown_on
    ) {
      errors.push("Groq selected_model has reached its shutdown date");
    }
  }

  const gate = policy.activation_gate ?? {};
  if (gate.live_benchmark_required !== true) {
    errors.push("Groq production activation must require a live benchmark");
  }
  if (!positiveInteger(gate.minimum_cases_per_model)) {
    errors.push("Groq benchmark minimum_cases_per_model must be positive");
  }
  if (
    !finiteNonNegative(gate.required_valid_rate) ||
    gate.required_valid_rate > 1
  ) {
    errors.push("Groq benchmark required_valid_rate must be between 0 and 1");
  }
  if (
    !Array.isArray(gate.candidate_models) ||
    gate.candidate_models.length < 2 ||
    gate.candidate_models.some((modelId) => !modelIds.has(modelId))
  ) {
    errors.push("Groq benchmark candidates must name at least two policy models");
  }
  return [...new Set(errors)];
}

function resolveGroqGenerationModel(
  policy,
  now = new Date().toISOString()
) {
  const errors = validateGroqProviderPolicy(policy, now);
  if (errors.length > 0) {
    throw new Error(`Invalid Groq provider policy:\n- ${errors.join("\n- ")}`);
  }
  return groqModelById(policy, policy.selected_model);
}

function groqScheduledCapacity(policy, generatorRuntime) {
  const model = resolveGroqGenerationModel(policy);
  for (const field of [
    "schedule_minutes",
    "per_run_cap",
    "execution_timeout_seconds"
  ]) {
    if (!positiveInteger(generatorRuntime?.[field])) {
      throw new Error(`Generator runtime ${field} must be a positive integer`);
    }
  }
  const generation = policy.generation;
  const initialRequestEstimate =
    Math.ceil(
      (generation.maximum_combined_input_characters -
        generation.repair_reserve_characters) /
        generation.character_estimate_divisor
    ) + generation.maximum_output_tokens;
  const repairRequestEstimate =
    Math.ceil(
      generation.maximum_combined_input_characters /
        generation.character_estimate_divisor
    ) + generation.maximum_output_tokens;
  const maximumScheduledExecutionsPerDay =
    Math.ceil((24 * 60) / generatorRuntime.schedule_minutes) + 1;
  const maximumScheduledRequestsPerDay =
    maximumScheduledExecutionsPerDay * generatorRuntime.per_run_cap * 2;
  const perItemEstimate = initialRequestEstimate + repairRequestEstimate;
  return {
    model_id: model.id,
    initial_request_character_token_estimate: initialRequestEstimate,
    repair_request_character_token_estimate: repairRequestEstimate,
    per_item_character_token_estimate: perItemEstimate,
    maximum_scheduled_executions_per_day:
      maximumScheduledExecutionsPerDay,
    maximum_scheduled_requests_per_day: maximumScheduledRequestsPerDay,
    maximum_scheduled_character_token_estimate_per_day:
      maximumScheduledExecutionsPerDay *
      generatorRuntime.per_run_cap *
      perItemEstimate,
    maximum_pacing_milliseconds:
      (2 * generatorRuntime.per_run_cap - 1) *
      generation.request_interval_ms
  };
}

function validateGroqRuntimeCapacity(policy, generatorRuntime) {
  const errors = validateGroqProviderPolicy(policy);
  for (const field of [
    "schedule_minutes",
    "per_run_cap",
    "execution_timeout_seconds"
  ]) {
    if (!positiveInteger(generatorRuntime?.[field])) {
      errors.push(`Generator runtime ${field} must be a positive integer`);
    }
  }
  if (errors.length > 0) return [...new Set(errors)];

  const model = groqModelById(policy, policy.selected_model);
  const limits = model.developer_base_limits;
  const capacity = groqScheduledCapacity(policy, generatorRuntime);
  if (
    capacity.initial_request_character_token_estimate >
    limits.tokens_per_minute
  ) {
    errors.push(
      "Groq initial-request character token estimate exceeds the selected model TPM limit"
    );
  }
  if (
    capacity.repair_request_character_token_estimate >
    limits.tokens_per_minute
  ) {
    errors.push(
      "Groq repair-request character token estimate exceeds the selected model TPM limit"
    );
  }
  if (
    capacity.maximum_scheduled_requests_per_day > limits.requests_per_day
  ) {
    errors.push(
      "Groq scheduled request ceiling exceeds the selected model RPD limit"
    );
  }
  if (
    capacity.maximum_scheduled_character_token_estimate_per_day >
    limits.tokens_per_day
  ) {
    errors.push(
      "Groq scheduled character token estimate exceeds the selected model TPD limit"
    );
  }
  if (
    capacity.maximum_pacing_milliseconds >=
    generatorRuntime.execution_timeout_seconds * 1000
  ) {
    errors.push("Groq request pacing exhausts the Generator execution timeout");
  }
  return [...new Set(errors)];
}

function groqInitialUserCharacterBudget(policy, systemMessage) {
  const budget =
    policy.generation.maximum_combined_input_characters -
    String(systemMessage || "").length -
    policy.generation.repair_reserve_characters;
  if (budget < 1000) {
    throw new Error("Groq policy leaves less than 1,000 characters for the job prompt");
  }
  return budget;
}

function validateGroqPromptBudget(policy, systemMessage, userMessage) {
  const combinedCharacters =
    String(systemMessage || "").length + String(userMessage || "").length;
  const maximum = policy?.generation?.maximum_combined_input_characters;
  return {
    valid: positiveInteger(maximum) && combinedCharacters <= maximum,
    combined_characters: combinedCharacters,
    maximum_characters: maximum,
    character_based_token_estimate: Math.ceil(
      combinedCharacters /
        Math.max(1, policy?.generation?.character_estimate_divisor || 1)
    )
  };
}

function estimateGroqCostUsd(model, usage = {}) {
  const prices = model?.pricing_usd_per_million_tokens ?? {};
  const inputTokens = Math.max(0, Number(usage.input_tokens) || 0);
  const cachedInputTokens = Math.min(
    inputTokens,
    Math.max(0, Number(usage.cached_input_tokens) || 0)
  );
  const uncachedInputTokens = inputTokens - cachedInputTokens;
  const outputTokens = Math.max(0, Number(usage.output_tokens) || 0);
  return (
    (uncachedInputTokens * (prices.input ?? 0) +
      cachedInputTokens * (prices.cached_input ?? prices.input ?? 0) +
      outputTokens * (prices.output ?? 0)) /
    1_000_000
  );
}

function evaluateGroqBenchmark(modelResults, policy) {
  const requiredCases = policy.activation_gate.minimum_cases_per_model;
  const requiredRate = policy.activation_gate.required_valid_rate;
  return (modelResults ?? []).map((result) => {
    const cases = Array.isArray(result.cases) ? result.cases : [];
    const valid = cases.filter((entry) => entry.valid === true).length;
    const validRate = cases.length === 0 ? 0 : valid / cases.length;
    return {
      model: result.model,
      case_count: cases.length,
      valid_count: valid,
      valid_rate: validRate,
      passes:
        cases.length >= requiredCases &&
        validRate >= requiredRate &&
        cases.every(
          (entry) =>
            finiteNonNegative(entry.latency_ms) &&
            positiveInteger(entry.input_tokens) &&
            positiveInteger(entry.output_tokens)
        )
    };
  });
}


function evaluatePersistedMessageSafety(
  record,
  { profile, applicationPolicy, packPolicy } = {}
) {
  if (!profile || !applicationPolicy || !packPolicy) {
    return {
      safe: false,
      reasons: ["message_safety_configuration_missing"]
    };
  }

  const reasons = [];
  const messageProfileVersion = String(
    record?.message_profile_version || ""
  ).trim();
  if (messageProfileVersion === "legacy/unknown") {
    reasons.push("message_profile_legacy");
  } else if (!messageProfileVersion) {
    reasons.push("message_profile_missing");
  } else if (messageProfileVersion !== profile.profile_version) {
    reasons.push("message_profile_mismatch");
  }

  const messagePolicyVersion = String(
    record?.message_policy_version || ""
  ).trim();
  if (!messagePolicyVersion) {
    reasons.push("message_policy_missing");
  } else if (messagePolicyVersion !== applicationPolicy.policy_version) {
    reasons.push("message_policy_mismatch");
  }
  if (record?.message_validation_status !== "valid") {
    reasons.push("message_validation_not_valid");
  }
  if (!String(record?.generated_message || "").trim()) {
    reasons.push("message_missing");
  }

  if (record?.application_pack_status !== "ready") {
    reasons.push("pack_status_not_ready");
  }
  if (record?.application_pack_version !== packPolicy.pack_version) {
    reasons.push("pack_version_mismatch");
  }
  if (
    record?.application_pack_profile_version !== profile.profile_version
  ) {
    reasons.push("pack_profile_mismatch");
  }
  if (
    record?.application_pack_policy_version !== packPolicy.policy_version
  ) {
    reasons.push("pack_policy_mismatch");
  }

  const packErrors = validateApplicationPack(record, profile, packPolicy);
  if (packErrors.length > 0) reasons.push("pack_invalid");
  const messageValidation = validateGeneratedMessage(
    record?.generated_message,
    {
      job: record,
      profile,
      policy: applicationPolicy,
      pack: record
    }
  );
  if (!messageValidation.valid) reasons.push("message_content_invalid");

  return {
    safe: reasons.length === 0,
    reasons
  };
}


const ALLOWED_CHANNELS = ["slack"];
const ENVIRONMENT_NAME = /^[A-Z][A-Z0-9_]{2,63}$/;
const ALERT_RENDER_ERROR_SUMMARIES = Object.freeze({
  message_code_block_unsafe:
    "The validated application message cannot be represented safely in a Slack code block.",
  message_control_characters:
    "The validated application message contains unsupported control characters.",
  message_too_long:
    "The complete application message and required actions exceed the configured Slack alert limit.",
  render_failure: "The Slack alert could not be rendered safely."
});

function slackLinkUrlSafe(value) {
  return !/[<>|]/u.test(String(value || ""));
}

function cleanText(value, maximum = 500) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[\u200b-\u200d\u2060\ufeff]/gi, "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .replace(
      /(api[_-]?key|token|authorization|password|secret)\s*[:=]\s*\S+/gi,
      "$1=[redacted]"
    )
    .trim()
    .slice(0, maximum);
}

function alertIdempotencyKey(record, policy) {
  const canonicalId = String(record?.canonical_job_id || "").trim();
  return canonicalId && policy?.policy_version
    ? `${canonicalId}|${policy.policy_version}`
    : "";
}

function validateAlertPolicy(policy) {
  const errors = [];
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    return ["alert policy must be an object"];
  }
  if (policy.schema_version !== 1) errors.push("alert policy schema_version must be 1");
  if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(policy.policy_version ?? "")) {
    errors.push("alert policy_version must use YYYY-MM-DD/vN");
  }
  if (!ALLOWED_CHANNELS.includes(policy.channel)) {
    errors.push("alert channel is unsupported");
  }
  for (const field of [
    "schedule_minutes",
    "per_run_cap",
    "execution_timeout_seconds",
    "claim_lease_ms",
    "provider_timeout_ms",
    "provider_request_interval_ms",
    "maximum_message_characters",
    "maximum_action_url_characters",
    "summary_item_characters"
  ]) {
    if (!Number.isInteger(policy[field]) || policy[field] < 1) {
      errors.push(`${field} must be a positive integer`);
    }
  }
  errors.push(...validateMinuteIntervalSchedule(policy, "alert"));
  if (
    !Number.isInteger(policy.retry?.max_attempts) ||
    policy.retry.max_attempts < 1 ||
    !Number.isInteger(policy.retry?.backoff_ms) ||
    policy.retry.backoff_ms < 1
  ) {
    errors.push("alert retry bounds are invalid");
  }
  if (
    Number.isInteger(policy.execution_timeout_seconds) &&
    Number.isInteger(policy.claim_lease_ms) &&
    policy.execution_timeout_seconds * 1000 >= policy.claim_lease_ms
  ) {
    errors.push(
      "alert claim lease must outlast the workflow execution timeout"
    );
  }
  if (
    Number.isInteger(policy.claim_lease_ms) &&
    Number.isInteger(policy.schedule_minutes) &&
    policy.claim_lease_ms >= policy.schedule_minutes * 60 * 1000
  ) {
    errors.push(
      "alert claim lease must expire before the next scheduled poll"
    );
  }
  if (
    Number.isInteger(policy.provider_request_interval_ms) &&
    policy.provider_request_interval_ms < 1000
  ) {
    errors.push(
      "Slack provider requests must be paced at least one second apart"
    );
  }
  if (
    Number.isInteger(policy.provider_timeout_ms) &&
    Number.isInteger(policy.execution_timeout_seconds) &&
    policy.provider_timeout_ms >= policy.execution_timeout_seconds * 1000
  ) {
    errors.push(
      "alert provider timeout must be shorter than the workflow execution timeout"
    );
  }
  if (
    Number.isInteger(policy.provider_timeout_ms) &&
    Number.isInteger(policy.provider_request_interval_ms) &&
    Number.isInteger(policy.per_run_cap) &&
    Number.isInteger(policy.execution_timeout_seconds) &&
    (
      policy.provider_timeout_ms * policy.per_run_cap +
      policy.provider_request_interval_ms *
        Math.max(0, policy.per_run_cap - 1)
    ) >=
      policy.execution_timeout_seconds * 1000
  ) {
    errors.push(
      "alert execution timeout must exceed capped serial provider timeouts and pacing"
    );
  }
  if (
    Number.isInteger(policy.retry?.backoff_ms) &&
    Number.isInteger(policy.claim_lease_ms) &&
    policy.retry.backoff_ms < policy.claim_lease_ms
  ) {
    errors.push(
      "alert retry backoff must not precede ProcessingClaims lease expiry"
    );
  }
  if (policy.retry?.ambiguous_timeout_terminal !== true) {
    errors.push("Slack ambiguous timeouts must be terminal to prevent blind duplicates");
  }
  if (
    Number.isInteger(policy.maximum_message_characters) &&
    Number.isInteger(policy.maximum_action_url_characters) &&
    policy.maximum_message_characters <
      policy.maximum_action_url_characters * 2 + 1000
  ) {
    errors.push(
      "maximum_message_characters must preserve two required links and context"
    );
  }
  for (const field of [
    "maximum_age_days",
    "minimum_qualification_score",
    "minimum_opportunity_score",
    "maximum_major_gaps"
  ]) {
    const value = policy.eligibility?.[field];
    if (!Number.isFinite(value) || value < 0) {
      errors.push(`eligibility.${field} must be non-negative`);
    }
  }
  for (const field of [
    "minimum_qualification_score",
    "minimum_opportunity_score"
  ]) {
    if (policy.eligibility?.[field] > 100) {
      errors.push(`eligibility.${field} must not exceed 100`);
    }
  }
  if (
    !Array.isArray(policy.eligibility?.allowed_confidence) ||
    policy.eligibility.allowed_confidence.length === 0 ||
    policy.eligibility.allowed_confidence.some(
      (value) => !["high", "medium", "low"].includes(value)
    )
  ) {
    errors.push("eligibility.allowed_confidence is invalid");
  }
  if (policy.eligibility?.required_pack_status !== "ready") {
    errors.push("alert eligibility must require a ready pack");
  }
  for (const [field, value] of Object.entries(policy.environment ?? {})) {
    if (
      !["provider_webhook_url", "review_url"].includes(field) ||
      !ENVIRONMENT_NAME.test(value ?? "")
    ) {
      errors.push(`invalid alert environment reference: ${field}`);
    }
  }
  if (Object.keys(policy.environment ?? {}).length !== 2) {
    errors.push("provider_webhook_url and review_url environment references are required");
  }
  return errors;
}

function validateAlertProviderConfiguration(
  { webhookUrl, reviewUrl },
  policy
) {
  const errors = [];
  const webhook = parseHttpUrl(webhookUrl);
  if (!webhook) {
    errors.push("provider webhook URL is missing or invalid");
  }
  if (
    webhook &&
    (webhook.protocol !== "https:" ||
      !["hooks.slack.com", "hooks.slack-gov.com"].includes(webhook.hostname) ||
      webhookUrl.length > policy.maximum_action_url_characters)
  ) {
    errors.push(
      "provider webhook URL must use an approved bounded Slack HTTPS host"
    );
  }
  const review = parseHttpUrl(reviewUrl);
  if (!review) {
    errors.push("review URL is missing or invalid");
  }
  if (
    review &&
    (review.protocol !== "https:" ||
      review.username ||
      review.password ||
      !slackLinkUrlSafe(reviewUrl) ||
      reviewUrl.length > policy.maximum_action_url_characters)
  ) {
    errors.push("review URL must use bounded credential-free HTTPS");
  }
  if (policy.channel !== "slack") errors.push("provider channel is unsupported");
  return errors;
}

function scoreKnown(value) {
  return typeof value === "number" && Number.isFinite(value);
}

function evaluateAlertEligibility(
  record,
  policy,
  now = new Date().toISOString(),
  messageSafetyContext
) {
  const reasons = [];
  if (!record?.canonical_job_id) reasons.push("missing_identity");
  const sourceUrl = normalizeCanonicalUrl(record?.canonical_url);
  if (
    !sourceUrl ||
    !slackLinkUrlSafe(sourceUrl) ||
    sourceUrl.length > policy.maximum_action_url_characters
  ) {
    reasons.push("source_url_invalid");
  }
  if (record?.pipeline_status !== "ready") reasons.push("lifecycle_not_ready");
  if (record?.application_decision) reasons.push("application_already_decided");
  if (record?.source_availability === "unavailable") reasons.push("source_unavailable");
  if (record?.application_pack_status !== policy.eligibility.required_pack_status) {
    reasons.push("pack_not_ready");
  }
  const messageSafety = evaluatePersistedMessageSafety(
    record,
    messageSafetyContext
  );
  if (!messageSafety.safe) reasons.push("message_quarantined");
  if (
    !scoreKnown(record?.qualification_score) ||
    record.qualification_score < policy.eligibility.minimum_qualification_score
  ) {
    reasons.push("qualification_below_threshold");
  }
  if (
    !scoreKnown(record?.opportunity_score) ||
    record.opportunity_score < policy.eligibility.minimum_opportunity_score
  ) {
    reasons.push("opportunity_below_threshold");
  }
  if (!policy.eligibility.allowed_confidence.includes(record?.ranking_confidence)) {
    reasons.push("confidence_not_allowed");
  }
  const majorGaps = (Array.isArray(record?.requirement_gap_details)
    ? record.requirement_gap_details
    : []
  ).filter((gap) => ["hard", "ambiguous"].includes(gap?.classification));
  if (majorGaps.length > policy.eligibility.maximum_major_gaps) {
    reasons.push("major_gap_limit_exceeded");
  }
  const nowMs = Date.parse(now);
  const postedMs = Date.parse(record?.posted_at || "");
  const postingAgeDays =
    Number.isFinite(nowMs) && Number.isFinite(postedMs) && postedMs <= nowMs
      ? (nowMs - postedMs) / (24 * 60 * 60 * 1000)
      : undefined;
  if (
    postingAgeDays === undefined ||
    postingAgeDays > policy.eligibility.maximum_age_days
  ) {
    reasons.push(
      record?.posted_at ? "posting_timestamp_invalid" : "posting_timestamp_missing"
    );
  }
  return {
    eligible: reasons.length === 0,
    reasons,
    posting_age_days: postingAgeDays,
    message_safety: messageSafety
  };
}

function queueAlertState(
  record,
  policy,
  now = new Date().toISOString(),
  messageSafetyContext
) {
  const eligibility = evaluateAlertEligibility(
    record,
    policy,
    now,
    messageSafetyContext
  );
  const key = alertIdempotencyKey(record, policy);
  if (record.alert_status === "sent") {
    return record;
  }
  if (record.source_availability === "unavailable") {
    return {
      ...record,
      alert_status: "suppressed",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: key,
      alert_suppressed_reason: "source_unavailable",
      alert_next_retry_at: "",
      updated_at: now
    };
  }
  if (!eligibility.eligible) {
    return {
      ...record,
      alert_status: "not_eligible",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: key,
      alert_suppressed_reason: eligibility.reasons.join(","),
      alert_next_retry_at: "",
      updated_at: now
    };
  }
  if (
    ["pending", "sending", "retryable_failure", "terminal_failure"].includes(
      record.alert_status
    )
  ) {
    return record;
  }
  return {
    ...record,
    alert_status: "pending",
    alert_channel: policy.channel,
    alert_policy_version: policy.policy_version,
    alert_idempotency_key: key,
    alert_attempt_count: 0,
    alert_last_attempt_at: "",
    alert_next_retry_at: now,
    alert_sent_at: "",
    alert_provider_reference: "",
    alert_error_category: "",
    alert_error_summary: "",
    alert_suppressed_reason: "",
    updated_at: now
  };
}

function retryDue(record, now) {
  if (!record.alert_next_retry_at) return true;
  const retryAt = Date.parse(record.alert_next_retry_at);
  return !Number.isFinite(retryAt) || retryAt <= Date.parse(now);
}

function selectAlertCandidates(
  rawRows,
  schema,
  policy,
  now = new Date().toISOString(),
  messageSafetyContext
) {
  const selected = [];
  for (const raw of rawRows) {
    const record = normalizeLegacyRecord(raw, schema, now);
    const safetyEligibility = evaluateAlertEligibility(
      record,
      policy,
      now,
      messageSafetyContext
    );
    if (
      !safetyEligibility.message_safety.safe &&
      ["pending", "sending", "retryable_failure"].includes(
        record.alert_status
      )
    ) {
      selected.push({
        ...queueAlertState(
          record,
          policy,
          now,
          messageSafetyContext
        ),
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "state_only"
      });
      continue;
    }
    if (record.alert_status === "sending") {
      if (
        !isStaleClaim(record, Date.parse(now), policy.claim_lease_ms)
      ) {
        continue;
      }
      selected.push({
        ...record,
        alert_status: "terminal_failure",
        alert_next_retry_at: "",
        alert_error_category: "ambiguous_delivery",
        alert_error_summary:
          "Delivery began but its final acknowledgement was not persisted; automatic resend was suppressed.",
        updated_at: now,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "state_only"
      });
      continue;
    }
    const queued = queueAlertState(
      record,
      policy,
      now,
      messageSafetyContext
    );
    const existingDeliveryState = ["pending", "retryable_failure"].includes(
      record.alert_status
    );
    if (!existingDeliveryState) continue;
    if (["suppressed", "not_eligible"].includes(queued.alert_status)) {
      selected.push({
        ...queued,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "state_only"
      });
      continue;
    }
    if (
      ["pending", "retryable_failure"].includes(queued.alert_status) &&
      retryDue(queued, now) &&
      evaluateAlertEligibility(
        queued,
        policy,
        now,
        messageSafetyContext
      ).eligible
    ) {
      selected.push({
        ...queued,
        row_number: raw.row_number,
        work_stage: "alert",
        delivery_mode: "deliver"
      });
    }
  }
  selected.sort(
    (left, right) =>
      Number(right.opportunity_score) - Number(left.opportunity_score) ||
      Date.parse(right.posted_at) - Date.parse(left.posted_at) ||
      left.canonical_job_id.localeCompare(right.canonical_job_id)
  );
  return {
    candidates: selected.slice(0, policy.per_run_cap),
    state_updates: []
  };
}

function confirmAlertAttemptMarkers(plannedRecords, freshRows) {
  const planned = Array.isArray(plannedRecords) ? plannedRecords : [];
  const current = (Array.isArray(freshRows) ? freshRows : []).filter(
    (row) => row && typeof row === "object" && !Array.isArray(row)
  );
  return planned.flatMap((record) => {
    const identity = String(record?.canonical_job_id || "").trim();
    const commitGuard = String(
      record?.processing_commit_guard || ""
    ).trim();
    const processingToken = String(record?.processing_token || "").trim();
    const stateGuard = String(record?.state_guard || "").trim();
    const alertStatus = String(record?.alert_status || "").trim();
    if (
      !identity ||
      !commitGuard ||
      !processingToken ||
      !stateGuard ||
      !alertStatus
    ) {
      return [];
    }
    const matches = current.filter(
      (candidate) =>
        String(candidate?.processing_commit_guard || "").trim() ===
        commitGuard
    );
    if (matches.length !== 1) return [];
    const persisted = matches[0];
    if (
      String(persisted.canonical_job_id || "").trim() !== identity ||
      String(persisted.processing_token || "").trim() !== processingToken ||
      String(persisted.processing_stage || "").trim() !== "alert" ||
      String(persisted.state_guard || "").trim() !== stateGuard ||
      String(persisted.alert_status || "").trim() !== alertStatus
    ) {
      return [];
    }
    return [{ ...record, row_number: persisted.row_number }];
  });
}

function summaryList(values, policy, fallback) {
  if (!Array.isArray(values) || values.length === 0) return fallback;
  return values
    .slice(0, 3)
    .map((value) =>
      cleanText(
        typeof value === "string"
          ? value
          : value.text || value.summary || value.requirement || "",
        policy.summary_item_characters
      )
    )
    .filter(Boolean)
    .join(" | ") || fallback;
}

function slackEscape(value) {
  return cleanText(value, 500)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function slackEscapeLiteral(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function alertRenderError(category) {
  const normalizedCategory =
    Object.hasOwn(ALERT_RENDER_ERROR_SUMMARIES, category)
      ? category
      : "render_failure";
  const error = new Error(ALERT_RENDER_ERROR_SUMMARIES[normalizedCategory]);
  error.name = "AlertRenderError";
  error.alert_category = normalizedCategory;
  return error;
}

function alertRenderErrorCategory(error) {
  const category = String(error?.alert_category || "");
  return Object.hasOwn(ALERT_RENDER_ERROR_SUMMARIES, category)
    ? category
    : "render_failure";
}

function fitAlertLines(lines, minimums, maximum) {
  if (!Number.isFinite(maximum) || maximum <= 0) return "";
  const result = lines.map((line, index) => ({
    text: line,
    minimum: minimums[index] ?? 0
  }));
  const length = () =>
    result.reduce((sum, line) => sum + line.text.length, 0) +
    Math.max(0, result.length - 1);
  while (length() > maximum) {
    let candidate = -1;
    let reducible = 0;
    for (let index = 0; index < result.length; index += 1) {
      const available =
        result[index].text.length - result[index].minimum;
      if (available > reducible) {
        candidate = index;
        reducible = available;
      }
    }
    if (candidate >= 0 && reducible > 0) {
      const excess = length() - maximum;
      const nextLength =
        result[candidate].text.length - Math.min(reducible, excess);
      result[candidate].text = `${result[candidate].text
        .slice(
          0,
          Math.max(
            result[candidate].minimum - 1,
            nextLength - 1
          )
        )
        .trimEnd()}…`;
      continue;
    }
    result.pop();
  }
  return result.map((line) => line.text).join("\n");
}

function renderAlert(
  record,
  policy,
  { reviewUrl, messageSafetyContext }
) {
  const messageSafety = evaluatePersistedMessageSafety(
    record,
    messageSafetyContext
  );
  if (!messageSafety.safe) {
    throw new Error(
      `message_quarantined: ${messageSafety.reasons.join(",")}`
    );
  }
  const normalizedSourceUrl = normalizeCanonicalUrl(record.canonical_url);
  const sourceUrl =
    slackLinkUrlSafe(normalizedSourceUrl) &&
    normalizedSourceUrl.length <= policy.maximum_action_url_characters
      ? normalizedSourceUrl
      : "";
  const parsedReviewUrl = parseHttpUrl(reviewUrl);
  const safeReviewUrl =
    parsedReviewUrl?.protocol === "https:" &&
    slackLinkUrlSafe(parsedReviewUrl.href) &&
    parsedReviewUrl.href.length <= policy.maximum_action_url_characters
      ? parsedReviewUrl.href
      : "";
  const age = evaluateAlertEligibility(
    record,
    policy,
    record.alert_last_attempt_at || new Date().toISOString(),
    messageSafetyContext
  ).posting_age_days;
  const employer = cleanText(record.company, 120) || "Unknown";
  const salary = cleanText(record.salary_text, 120) || "Unknown";
  const instructions = summaryList(
    record.application_instructions,
    policy,
    "None detected"
  );
  const questions = summaryList(
    record.screening_questions,
    policy,
    "None detected"
  );
  const proofs = summaryList(record.selected_proof_refs, policy, "None selected");
  const warnings = summaryList(record.application_warnings, policy, "None");
  const gaps = summaryList(record.requirement_gap_details, policy, "None");
  const links = [
    safeReviewUrl ? `<${safeReviewUrl}|Open Review Queue>` : "Review Queue: unavailable",
    sourceUrl ? `<${sourceUrl}|Open OnlineJobs.ph>` : "Source: unavailable"
  ].join(" · ");
  const applicationMessage = String(record.generated_message ?? "");
  if (
    applicationMessage.includes("```") ||
    applicationMessage.startsWith("`") ||
    applicationMessage.endsWith("`")
  ) {
    throw alertRenderError("message_code_block_unsafe");
  }
  if (
    /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f\u200b-\u200d\u2060\ufeff]/u.test(
      applicationMessage
    )
  ) {
    throw alertRenderError("message_control_characters");
  }
  const applicationBlock =
    `*Application message — copy below:*\n` +
    `\`\`\`${slackEscapeLiteral(applicationMessage)}\`\`\``;
  const requiredTail = `${applicationBlock}\n${links}`;
  if (requiredTail.length > policy.maximum_message_characters) {
    throw alertRenderError("message_too_long");
  }
  const contextLines = [
    `*High-opportunity job:* ${slackEscape(record.job_title) || "Untitled role"}`,
    `Qualification ${record.qualification_score}/100 · Opportunity ${record.opportunity_score}/100 · Confidence ${record.ranking_confidence}`,
    `Employer: ${slackEscape(employer)} · Salary: ${slackEscape(salary)} · Freshness: ${
      Number.isFinite(age) ? `${Math.round(age * 10) / 10} days` : "Unknown"
    }`,
    `Apply Points: ${record.apply_points_recommendation || "Unknown"} · Major gaps: ${slackEscape(gaps)}`,
    `Instructions: ${slackEscape(instructions)}`,
    `Questions: ${slackEscape(questions)}`,
    `Proofs: ${slackEscape(proofs)}`,
    `Warnings: ${slackEscape(warnings)}`
  ];
  const context = fitAlertLines(
    contextLines,
    [60, 80, 100, 100, 120, 120, 120, 180],
    policy.maximum_message_characters - requiredTail.length - 1
  );
  const text = context
    ? `${context}\n${requiredTail}`
    : requiredTail;
  if (text.length > policy.maximum_message_characters) {
    throw alertRenderError("message_too_long");
  }
  return {
    channel: policy.channel,
    idempotency_key: alertIdempotencyKey(record, policy),
    text,
    review_action: {
      mode: "authorized_review_surface",
      url: safeReviewUrl
    },
    source_action: {
      mode: "open_only",
      url: sourceUrl
    }
  };
}

function alertProviderErrorMessage(result) {
  const error = result?.error;
  return cleanText(
    (typeof error === "string" ? error : error?.message || error?.description) ||
      result?.errorMessage ||
      result?.error_description ||
      result?.message ||
      result?.body ||
      "",
    200
  );
}

function classifyAlertProviderResult(
  result,
  policy,
  now = new Date().toISOString()
) {
  const message = alertProviderErrorMessage(result);
  const explicitStatus = Number(result?.statusCode || result?.status || 0);
  const inferredStatus = Number(
    message.match(/\b([45]\d{2})\b/)?.[1] || 0
  );
  const status = explicitStatus || inferredStatus;
  if (result?.preflight_error) {
    const category = String(result.preflight_error);
    const normalizedCategory =
      Object.hasOwn(ALERT_RENDER_ERROR_SUMMARIES, category)
        ? category
        : "render_failure";
    return {
      success: false,
      retryable: false,
      category: normalizedCategory,
      summary: ALERT_RENDER_ERROR_SUMMARIES[normalizedCategory],
      at: now
    };
  }
  if (result?.configuration_error) {
    return {
      success: false,
      retryable: false,
      category: "configuration_error",
      summary: cleanText(result.configuration_error, 200),
      at: now
    };
  }
  if (status >= 200 && status < 300 && /^(?:ok)?$/i.test(message)) {
    return {
      success: true,
      retryable: false,
      category: "",
      summary: "",
      provider_reference: cleanText(result.provider_reference, 120),
      at: now
    };
  }
  const timeout = status === 0 && /timeout|timed out|aborted/i.test(message);
  if (timeout && policy.retry.ambiguous_timeout_terminal) {
    return {
      success: false,
      retryable: false,
      category: "ambiguous_timeout",
      summary: "Provider timeout has ambiguous delivery; manual reconciliation required.",
      at: now
    };
  }
  const rateLimited =
    status === 429 || /rate.?limit|too many requests/i.test(message);
  const transientProviderFailure =
    status >= 500 ||
    (status === 0 &&
      /temporar|connection|econn|network|socket|service unavailable/i.test(
        message
      ));
  const retryable = rateLimited || transientProviderFailure;
  return {
    success: false,
    retryable,
    category:
      rateLimited
        ? "rate_limit"
        : transientProviderFailure
          ? "provider_failure"
          : status >= 400
            ? "provider_rejected"
            : "provider_malformed_response",
    summary: message || "Provider response was not a confirmed success.",
    at: now
  };
}

function applyAlertProviderResult(record, result, policy) {
  const outcome = classifyAlertProviderResult(result, policy, result?.at);
  const attempts = Number(record.alert_attempt_count || 0) + 1;
  if (outcome.success) {
    return releaseClaim(
      {
        ...record,
        alert_status: "sent",
        alert_channel: policy.channel,
        alert_policy_version: policy.policy_version,
        alert_idempotency_key: alertIdempotencyKey(record, policy),
        alert_attempt_count: attempts,
        alert_last_attempt_at: outcome.at,
        alert_next_retry_at: "",
        alert_sent_at: outcome.at,
        alert_provider_reference: outcome.provider_reference || "",
        alert_error_category: "",
        alert_error_summary: "",
        alert_suppressed_reason: "",
        updated_at: outcome.at
      },
      record.processing_token,
      outcome.at
    );
  }
  const retryable =
    outcome.retryable && attempts < policy.retry.max_attempts;
  return releaseClaim(
    {
      ...record,
      alert_status: retryable ? "retryable_failure" : "terminal_failure",
      alert_channel: policy.channel,
      alert_policy_version: policy.policy_version,
      alert_idempotency_key: alertIdempotencyKey(record, policy),
      alert_attempt_count: attempts,
      alert_last_attempt_at: outcome.at,
      alert_next_retry_at: retryable
        ? new Date(
            Date.parse(outcome.at) +
              policy.retry.backoff_ms * 2 ** (attempts - 1)
          ).toISOString()
        : "",
      alert_error_category: outcome.category,
      alert_error_summary: cleanText(outcome.summary, 200),
      updated_at: outcome.at
    },
    record.processing_token,
    outcome.at
  );
